import os
import requests
from datetime import datetime, timedelta, timezone

DATADOG_API_HOST = "https://api.datadoghq.com"
LOGS_SEARCH_ENDPOINT = f"{DATADOG_API_HOST}/api/v2/logs/events/search"

def query_recent_logs(service_name, status_code, start_time, end_time, limit=100):
    api_key = os.environ.get("DD_API_KEY")
    app_key = os.environ.get("DD_APP_KEY")
    if not api_key or not app_key:
        raise ValueError("DD_API_KEY and DD_APP_KEY environment variables must be set.")

    headers = {
        "DD-API-KEY": api_key,
        "DD-APPLICATION-KEY": app_key,
        "Content-Type": "application/json"
    }

    query_string = f"service:{service_name} @http.status_code:{status_code}"

    payload = {
        "data": {
            "attributes": {
                "filter": {
                    "query": query_string,
                    "from": start_time.isoformat(),
                    "to": end_time.isoformat()
                },
                "page": {
                    "limit": limit
                },
                "sort": "-timestamp"
            }
        }
    }

    response = requests.post(LOGS_SEARCH_ENDPOINT, headers=headers, json=payload)
    response.raise_for_status()

    return response.json().get("data", [])

if __name__ == "__main__":
    now = datetime.now(timezone.utc)
    window_start = now - timedelta(hours=1)

    logs = query_recent_logs(
        service_name="payment-service",
        status_code="500",
        start_time=window_start,
        end_time=now,
        limit=25
    )

    for log_event in logs:
        attrs = log_event.get("attributes", {})
        print(f"[{attrs.get('timestamp')}] {attrs.get('message', 'No message')}")
